@pytest.mark.parametrize('vertical', ['FLIGHT','RAIL']) def test_delayed_checkout_writeback_does_not_regress_confirmed_tickets(monkeypatch,vertical): from threading import Event, current_thread from go_hotel.services.vertical_transaction_bridge import vertical_transaction_bridge as bridge from go_hotel.services.order_supplier_fulfillment import order_supplier_fulfillment_service as fulfillment svc, oid = pending_order(vertical) original = bridge.checkout_contract entered, finish = Event(), Event() def paused(*args, **kwargs): result = original(*args, **kwargs) if current_thread().name.startswith('delayed-checkout'): entered.set() assert finish.wait(15) return result monkeypatch.setattr(bridge,'checkout_contract',paused) with ThreadPoolExecutor(max_workers=1,thread_name_prefix='delayed-checkout') as pool: first = pool.submit(svc.checkout,'owner',oid,'isolated') try: assert entered.wait(15) svc.checkout('owner',oid,'isolated') fid, body = supplier_fact(oid,['ISOLATED-1']) fulfillment.record_supplier_fact(fid,body) assert svc.order('owner',oid)['status']=='TICKETED' finally: finish.set() > assert first.result(timeout=15)['status']=='TICKETED' E AssertionError: assert 'PAYMENT_CONF...TING_SUPPLIER' == 'TICKETED' E E - TICKETED E + PAYMENT_CONFIRMED_AWAITING_SUPPLIER
